/**
 * Thai / English strings for the web app (LIFF) and the bot's standard
 * replies. One dictionary, loaded by Node (src/) and served unchanged to the
 * browser (/app/shared/i18n.js).
 *
 * Thai is the default and the fallback. Keys use {name} placeholders.
 * Never translate user content: file names, titles, saved facts, links,
 * amounts and timestamps pass through untouched.
 */

export const LANGS = ['th', 'en'];
export const DEFAULT_LANG = 'th';
export const TONES = ['polite', 'friend'];

export function normalizeLang(l) {
  return l === 'en' ? 'en' : 'th';
}

export function normalizeTone(t) {
  return t === 'friend' ? 'friend' : 'polite';
}

