Object.assign(th, botTh);
Object.assign(en, botEn);

export const STRINGS = { th, en };

/** Look up a string; falls back to Thai, then to the key itself. */
export function t(lang, key, vars) {
  const table = STRINGS[normalizeLang(lang)];
  let s = table[key] ?? th[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
  return s;
}

/** Bound lookup: const T = translator('en'); T('save') */
export function translator(lang) {
  const l = normalizeLang(lang);
  const fn = (key, vars) => t(l, key, vars);
  fn.lang = l;
  return fn;
}
